def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator and compare the equal-sized panels on either side.
    for r in range(h):
        if len(set(grid[r])) == 1 and h % 2 == 1:
            n = r
            if r == n and h - r - 1 == n:
                return [
                    [2 if grid[i][j] != 0 and grid[r + 1 + i][j] != 0 else 0
                     for j in range(w)]
                    for i in range(n)
                ]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and w % 2 == 1:
            n = c
            if c == n and w - c - 1 == n:
                return [
                    [2 if grid[i][j] != 0 and grid[i][c + 1 + j] != 0 else 0
                     for j in range(n)]
                    for i in range(h)
                ]

    return grid
